package Test {
  operation def sqrt(v: real) returns real { return v / 2.0; }
  component def D { attribute r: real = 0.0; operation go() { r = sqrt(8.0); } schedule { on start go(); } }
  component Demo: D;
}

package Types {
  operation def clampInt(v: int, low: int, high: int) returns int { if (v < low) { return low; } if (v > high) { return high; } return v; }
  operation def minInt(a: int, b: int) returns int { if (a < b) { return a; } return b; }
  operation def maxInt(a: int, b: int) returns int { if (a > b) { return a; } return b; }
  operation def clamp(v: real, low: real, high: real) returns real { if (v < low) { return low; } if (v > high) { return high; } return v; }
}
package Test {
  import Swaml::Math;
  import Types;
  component def D {
    attribute c: int = 0; attribute r: real = 0.0;
    operation go() { c = clampInt(12, 0, 10) * 100 + minInt(3, 4) * 10 + maxInt(1, 2); r = clamp(abs(-3.5), 0.0, 2.0) + max(1.0, 0.5); }
    schedule { on start go(); }
  }
  component Demo: D;
}

package Test {
  import Swaml::Math;
  component def D {
    attribute base: uint = 3;
    attribute t: uint = now();
    operation now() returns uint { return base; }
  }
  component Demo: D;
}

package Test {
  component def D {
    attribute clock: uint = 0;
    attribute last: uint = 0;
    operation now() returns uint { return clock; }
    operation tick() { clock = clock + 1; }
    operation go() { var t: uint = now(); wait 1ms; last = t; }
    schedule { on start go(); on every 500us tick(); }
  }
  component Demo: D;
}

package Time {
  operation def now() returns uint { return 7; }
}
package Test {
  import Time;
  component def D { attribute t: uint = 0; operation go() { t = now() + Time::now(); } schedule { on start go(); } }
  component Demo: D;
}

package Numeric {
  enum Text { Time, Numeric }
  component def Time {
    attribute Numeric: int = 2;
    attribute kind: Text = Text.Time;
    operation Text2() returns int { return Numeric; }
  }
}
package Test {
  import Numeric;
  component def D {
    component Time: Numeric::Time;
    attribute Text: int = 0;
    attribute kind: Numeric::Text = Numeric::Text.Numeric;
    operation Numeric() returns int { return 5; }
    operation go() { Text = Numeric(); }
    schedule { on start go(); }
  }
  component Demo: D;
}

package Fmt {
  operation def intText(v: int) returns string { if (v < 0) { return "neg"; } return "pos"; }
  operation def realText(v: real, decimals: uint) returns string { if (decimals > 1) { return "many"; } return "few"; }
  operation def boolText(v: bool) returns string { if (v) { return "yes"; } return "no"; }
}
package Test {
  import Fmt;
  import Swaml::Math;
  component def D {
    attribute s: string = "";
    operation go() { s = concat(intText(-3), concat(realText(1.5, 2), boolText(true))); }
  }
  component demo: D;
  test 'Formats' of demo {
    demo.go();
    assert demo.s == "negmanyyes";
  }
}

package A { operation def sqrt(v: real) returns real { return v; } }
package B { operation def sqrt(v: real) returns real { return v + 1.0; } }
package Test {
  import A;
  import B;
  import Swaml::Math;
  component def D { attribute r: real = 0.0; operation go() { r = sqrt(4.0); } schedule { on start go(); } }
  component Demo: D;
}

package A { operation def now() returns uint { return 1; } }
package B { operation def now() returns uint { return 2; } }
package Test {
  import Swaml::Math;
  import A;
  import B;
  operation def abs(v: real) returns real { return v; }
  component def D { attribute r: real = 0.0; attribute t: uint = 0; operation go() { r = abs(-1.0); t = now(); } }
  component Demo: D;
}

package Test {
  import Swaml::Math;
  component def D {
    attribute t: uint = 0; attribute r: real = 0.0; attribute s: string = "";
    operation go() { t = now(); r = sqrt(2.0); s = intText(3); r = Swaml::Math::sqrt(2.0); r = clamp(1.0, 0.0, 2.0); t = clampInt(1, 0, 2); }
  }
  component Demo: D;
}

package Test {
  import Swaml::Math;
  component def D {
    attribute t: uint = 0; attribute r: real = 0.0;
    operation scale(now: uint, sqrt: real) returns real { return sqrt * 2.0 + now; }
    operation go() { var now: uint = 5; var intText: int = 2; var sqrt: real = scale(now, 1.5); t = now + intText; r = sqrt; }
    schedule { on start go(); }
  }
  component Demo: D;
}

package Test {
  import Swaml::Math;
  import Swaml::Calls;
  import Swaml::Qos;
  import Swaml::Platform;
  import Swaml::Views;
  operation def sqrt(v: real) returns real { return v * 0.5; }
  operation def now() returns uint { return 11; }
  operation def intText(v: int) returns string { return "i"; }
  operation def realText(v: real, decimals: uint) returns string { return "r"; }
  operation def boolText(v: bool) returns string { return "b"; }
  operation def clamp(v: real, low: real, high: real) returns real { return low; }
  operation def clampInt(v: int, low: int, high: int) returns int { return high; }
  operation def minInt(a: int, b: int) returns int { return 0 - 1; }
  operation def maxInt(a: int, b: int) returns int { return 99; }
  component def D {
    attribute r: real = 0.0; attribute t: uint = 0; attribute s: string = ""; attribute k: int = 0;
    attribute f: CallFailure = CallFailure.timeout;
    operation go() { r = sqrt(9.0) + clamp(5.0, 1.0, 2.0) + floor(2.5); t = now(); s = concat(intText(1), concat(realText(1.0, 2), boolText(false))); k = clampInt(0, 1, 2) + minInt(1, 2) + maxInt(1, 2); }
    schedule { on start go(); }
  }
  component Demo: D;
}

package Test {
  component def D {
    attribute base: uint = 3;
    operation now() returns uint { return base; }
  }
  component demo: D;
  test 'Clock helper' of demo {
    var now: uint = demo.now();
    assert now == 3;
  }
}

package Test {
  component def D {
    attribute t: uint = 0; attribute r: real = 0.0;
    operation go() {
      operation now() returns uint { return 9; }
      operation sqrt(v: real) returns real { return v; }
      t = now();
      r = sqrt(4.0);
    }
    schedule { on start go(); }
  }
  component Demo: D;
}

package Test {
  datatype Sample { now: uint; sqrt: real; Time: int; }
  requirement R { attribute now: uint = 5; attribute Time: int = 1; }
  component def D {
    attribute s: Sample = record Sample { now = 1; sqrt = 2.0; Time = 3; };
    attribute k: uint = 0;
    operation go() { k = s.now + 1; }
    schedule { on start go(); }
  }
  component Demo: D;
}

package Test {
  import Swaml::*;
  component def D { }
  component Demo: D;
}

package Test {
  import Swaml;
  component def D { attribute t: uint = 0; }
  component Demo: D;
}

package Test {
  operation def now() returns uint { return 4; }
  port def P { provides event e(v: int); }
  component def D {
    reversed port p: P;
    attribute t: uint = now();
    attribute seen: uint = 0;
    operation go() {
      initial Idle;
      state Idle {
        on entry { seen = seen + 1; }
        on receive p.e(v) when (now() == 4) to Done { seen = seen + 10; }
      }
      final state Done { }
    }
    schedule { on start go(); }
  }
  component def Env { port p: P; operation fire() { publish p.e(1); } schedule { on start fire(); } }
  component env: Env;
  component Demo: D;
  connect (env.p, Demo.p);
}

package A { datatype Time { n: int; } enum Numeric { one } }
package B { enum Time { x } datatype Numeric { v: real; } }
package Test {
  import Swaml::Math;
  import A;
  import B;
  component def D { attribute t: Time = Time.x; attribute k: Numeric = Numeric.one; }
  component Demo: D;
}
